'use strict';
(()=>{
 let ctx,master,compressor,noise,dance=null,offset=0,audition=false,canPlay=false,nextStep=-1,lastKey='',media=null,mediaVersion=0,lastMediaSync=0,state='muted';const nodes=new Set();
 function report(value){if(value===state)return;state=value;window.dispatchEvent(new CustomEvent('dance-audio-state',{detail:value}))}
 function unlock(){try{ctx??=new(window.AudioContext||window.webkitAudioContext)();if(!master){master=ctx.createGain();compressor=ctx.createDynamicsCompressor();compressor.threshold.value=-15;compressor.ratio.value=5;master.connect(compressor);compressor.connect(ctx.destination);noise=ctx.createBuffer(1,ctx.sampleRate*.25,ctx.sampleRate);let seed=71;const a=noise.getChannelData(0);for(let i=0;i<a.length;i++){seed=seed*16807%2147483647;a[i]=seed/1073741823.5-1}}if(ctx.state!=='running')ctx.resume().catch(()=>report('blocked'));if(media)media.play().catch(()=>report('blocked'));return ctx}catch{report('error')}}
 function stop(){for(const n of nodes)try{n.stop()}catch{}nodes.clear();if(media){media.pause()}nextStep=-1}
 function tone(freq,time,duration,volume,type='sine',slide=null){const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,time);if(slide)o.frequency.exponentialRampToValueAtTime(slide,time+duration*.8);g.gain.setValueAtTime(.0001,time);g.gain.exponentialRampToValueAtTime(volume,time+.008);g.gain.exponentialRampToValueAtTime(.0001,time+duration);o.connect(g);g.connect(master);o.start(time);o.stop(time+duration+.02);nodes.add(o);o.onended=()=>{nodes.delete(o);o.disconnect();g.disconnect()}}
 function hat(time,open=false,snare=false){const n=ctx.createBufferSource(),f=ctx.createBiquadFilter(),g=ctx.createGain();n.buffer=noise;f.type='highpass';f.frequency.value=snare?1300:6500;g.gain.setValueAtTime(snare?.12:open?.065:.04,time);g.gain.exponentialRampToValueAtTime(.0001,time+(snare?.13:open?.15:.04));n.connect(f);f.connect(g);g.connect(master);n.start(time);n.stop(time+.2);nodes.add(n);n.onended=()=>{nodes.delete(n);n.disconnect();f.disconnect();g.disconnect()}}
 const midi=n=>440*2**((n-69)/12);
 function sequence(step,time){const s=dance.settings,bar=Math.floor(step/16),i=((step%16)+16)%16,track=s.track,chord=[0,5,3,7][Math.floor(bar/2)%4],root=(track==='pulse'?38:track==='sunrise'?45:42)+chord,beat=60/s.bpm;
 if(i%4===0){tone(135,time,.17,.48,'sine',43);tone(210,time,.025,.05,'triangle',60)}if(i===4||i===12){hat(time,false,true);tone(175,time,.09,.08,'triangle',95)}if(i%2===0)hat(time,i%4===2);if(track==='pulse'&&i%4===3)hat(time+.012);
 const bassPattern=track==='pulse'?[0,null,0,12,null,7,0,null,0,null,12,7,null,0,null,7]:[0,null,null,0,7,null,12,null,0,null,null,7,0,null,12,null];if(bassPattern[i]!==null)tone(midi(root+bassPattern[i]),time,beat*.34,.16,'triangle');
 if(i===0||i===6||i===10){for(const interval of [12,15,19])tone(midi(root+interval),time,beat*.8,.026,'sine')}
 const melody=track==='sunrise'?[24,27,31,34,31,27,26,22]:track==='pulse'?[24,22,19,22,24,31,27,22]:[24,31,27,22,24,34,31,27];if(i%2===0&&(bar%4!==3||i<8)){const n=melody[(i/2+Math.floor(bar/4))%8];tone(midi(root+n),time+.01,beat*.42,.035,track==='pulse'?'triangle':'sine')}
 }
 function tick(){if(!dance)return;const s=dance.settings,wanted=canPlay&&s.running&&(s.music||audition);if(!wanted){if(state!=='muted'){stop();report('muted')}return}if(!ctx)unlock();if(ctx?.state!=='running'){report('blocked');return}master.gain.setTargetAtTime((s.volume/100)*.65,ctx.currentTime,.08);const key=[s.track,s.bpm,dance.epoch,dance.musicVersion].join(':');if(key!==lastKey){stop();lastKey=key}const now=Date.now()+offset;if(s.track==='upload'){if(!dance.musicVersion){report('no-track');return}if(mediaVersion!==dance.musicVersion){media?.pause();media=new Audio('/dance-music?v='+dance.musicVersion);media.loop=true;media.preload='auto';mediaVersion=dance.musicVersion;media.oncanplay=()=>{if(dance?.settings.running&&(dance.settings.music||audition))media.play().then(()=>report('playing')).catch(()=>report('blocked'))};media.onerror=()=>report('error')}media.volume=s.volume/100;if(Number.isFinite(media.duration)&&media.duration>0&&now-lastMediaSync>3000){const desired=Math.max(0,(now-dance.epoch)/1000)%media.duration;if(Math.abs(media.currentTime-desired)>.3)media.currentTime=desired;lastMediaSync=now}if(media.paused)media.play().then(()=>report('playing')).catch(()=>report('blocked'));return}if(media&&!media.paused)media.pause();const elapsed=Math.max(0,(now-dance.epoch)/1000),stepSeconds=60/s.bpm/4,currentStep=Math.floor(elapsed/stepSeconds);if(nextStep<currentStep||nextStep>currentStep+5)nextStep=currentStep+1;while(nextStep*stepSeconds<elapsed+.14){sequence(nextStep,ctx.currentTime+Math.max(.005,nextStep*stepSeconds-elapsed));nextStep++}if(state!=='playing')report('playing')}
 setInterval(tick,25);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&ctx?.state==='suspended'&&(dance?.settings.music||audition))unlock()});window.DanceAudio={unlock,update(d,serverOffset,allowed){dance=d;offset=serverOffset;canPlay=allowed||audition},listen(){audition=!audition;canPlay=audition;unlock();if(!audition)stop();return audition},get state(){return state},get context(){return ctx},stop};
})();
